// Builds the text of the privacy policy and the terms from facts: who runs the app, what it uses and what it sells.
// Pure functions (no files, no network) so tests can snapshot the result. The text is plain English, short sentences,
// and never holds a placeholder: anything missing stops the build and is asked for in chat instead.
import { runInNewContext } from 'node:vm';
import { parseCountry, privacyRegion, hasWithdrawalRight, isEea, isUk, withArticle } from './countries.mjs';

export const DEFAULT_MIN_AGE = 16;
export const GENERATED_HEADER = [
  '// Generated by Shipyard (legal-generate). Run it again to rewrite this file; do not edit it by hand.',
  '// It is a clear first draft, not legal advice: have it checked before you take payments.',
].join('\n');

const REGION_LABELS = {
  'eu-central-1': 'Frankfurt, Germany',
  'eu-central-2': 'Zurich, Switzerland',
  'eu-west-1': 'Ireland',
  'eu-west-2': 'London, United Kingdom',
  'eu-west-3': 'Paris, France',
  'eu-north-1': 'Stockholm, Sweden',
  'us-east-1': 'North Virginia, United States',
  'us-east-2': 'Ohio, United States',
  'us-west-1': 'California, United States',
  'us-west-2': 'Oregon, United States',
  'ca-central-1': 'Canada',
  'sa-east-1': 'Sao Paulo, Brazil',
  'ap-south-1': 'Mumbai, India',
  'ap-southeast-1': 'Singapore',
  'ap-southeast-2': 'Sydney, Australia',
  'ap-northeast-1': 'Tokyo, Japan',
  'ap-northeast-2': 'Seoul, South Korea',
};

/** "eu-central-1" -> "Frankfurt, Germany"; an unknown code is shown as it is. */
export const regionLabel = (code) => REGION_LABELS[code] ?? `the region ${code}`;

const DASHES = /[\u2014\u2015]/g;
const HEX_LIKE = /#(?=[0-9a-fA-F]{3,8}(?![\w-]))/g;

/** Make user-typed text safe for the app's own checks: no em dashes, no "#abc" that looks like a colour, one line. */
export function cleanField(value) {
  return String(value ?? '')
    .replace(/[\u0000-\u001f\u007f\u2028\u2029]+/g, ' ')
    .replace(DASHES, '-')
    .replace(HEX_LIKE, 'No. ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** "Pro" "EUR 9.00 per month" from cents. Zero-decimal currencies (JPY) are handled by Intl. */
export function formatPrice(priceCents, currency, interval) {
  const code = String(currency || 'EUR').toUpperCase();
  let digits = 2;
  try {
    digits = new Intl.NumberFormat('en', { style: 'currency', currency: code }).resolvedOptions().maximumFractionDigits;
  } catch {
    digits = 2;
  }
  const amount = (priceCents / 10 ** digits).toFixed(digits);
  return `${code} ${amount} per ${interval === 'year' ? 'year' : 'month'}`;
}

const list = (items) => {
  const xs = items.filter(Boolean);
  if (xs.length <= 1) return xs.join('');
  return `${xs.slice(0, -1).join(', ')} and ${xs.at(-1)}`;
};

const sentence = (text) => {
  const t = String(text).trim();
  return /[.!?]$/.test(t) ? t : `${t}.`;
};

function safeguards(service) {
  const t = service.transfers ?? {};
  if (t.sccs && t.dpf) return 'standard contractual clauses and the EU-US Data Privacy Framework';
  if (t.sccs) return 'standard contractual clauses';
  if (t.dpf) return 'the EU-US Data Privacy Framework';
  return '';
}

const has = (services, id) => services.some((s) => s.id === id);
const anyFlag = (services, flag) => services.some((s) => s.flags?.[flag]);
const namesOf = (services, pred) => services.filter(pred).map((s) => s.name);

/**
 * @param {object} i
 * i.appName, i.appDescription, i.controller {name,address,email,vatId}, i.country {code,name}, i.services (catalogue entries),
 * i.modules (array of names), i.plans (array from plans.ts or null), i.supabaseRegion {code}, i.minAge, i.today (YYYY-MM-DD)
 */
export function buildLegalContent(i) {
  const app = cleanField(i.appName);
  const country = i.country;
  const services = i.services;
  const modules = new Set(i.modules ?? []);
  const minAge = i.minAge ?? DEFAULT_MIN_AGE;
  const region = privacyRegion(country.code);
  const billing = modules.has('billing') || has(services, 'stripe');
  const newsletter = modules.has('newsletter');
  const ai = anyFlag(services, 'ai');
  const analytics = anyFlag(services, 'analytics');
  const errors = anyFlag(services, 'errors');
  const google = has(services, 'google');
  const upstash = has(services, 'upstash');
  const resend = has(services, 'resend');
  const aiNames = namesOf(services, (s) => s.flags?.ai);
  const analyticsNames = namesOf(services, (s) => s.flags?.analytics);

  const controller = {
    name: cleanField(i.controller.name),
    address: cleanField(i.controller.address),
    email: cleanField(i.controller.email),
    country: country.name,
  };
  // A phone number is asked for when the app sells to consumers. "none" means the owner really has no phone: leave it out.
  const phone = cleanField(i.controller.phone);
  if (phone && phone.toLowerCase() !== 'none') controller.phone = phone;
  const vat = cleanField(i.controller.vatId);
  const paid = (i.plans ?? []).filter((p) => p.priceCents > 0);
  const freePlan = (i.plans ?? []).find((p) => p.priceCents === 0);
  const place = withArticle(country.name);
  const lawPlace = cleanField(i.governingLaw) || place;
  const description = cleanField(i.appDescription);
  const usefulDescription = description && !/made with shipyard/i.test(description) ? sentence(description) : '';

  // ---------------------------------------------------------------- privacy
  const privacy = [];

  privacy.push({
    id: 'who-we-are',
    title: 'Who we are',
    paragraphs: [
      `${app} is run by ${controller.name}, ${controller.address}, ${controller.country}. We decide why and how your personal data is used. The law calls this being the "controller" of your data.`,
      ...(vat ? [`VAT number: ${vat}.`] : []),
      `You can reach us at ${controller.email}${controller.phone ? ` or by phone on ${controller.phone}` : ''}. Write to the email address for any question about your data.`,
    ],
  });

  const collect = [
    'Your email address and your password. Your password is stored scrambled, so nobody can read it, not even us.',
    'The profile details you choose to add, such as a display name and a short bio.',
    'What you create or save in the app.',
    'Technical details that come with every visit: your IP address, browser and device type, the pages you open and the time. Our hosting provider records them in server logs. We use them to keep the app secure and to find faults.',
    'A sign-in cookie, so you stay signed in. More about cookies below.',
  ];
  if (google) collect.push('If you sign in with Google: your name and email address, which Google sends to us. We never see your Google password.');
  if (resend) collect.push('The emails we send you, for example to confirm your email address or to reset your password.');
  if (newsletter) collect.push('If you tick the box for email updates: your email address, the fact that you agreed, and the date and place where you agreed (the sign-up form or Settings).');
  if (billing) {
    collect.push('If you buy a paid plan: Stripe collects your payment details and billing address at checkout. We never see or store your card number. We keep your Stripe customer number, the plan you are on, its status and the date it renews.');
  }
  if (ai) collect.push(`If you use an AI feature: the text, files or questions you send to it, and the answer. They are sent to ${list(aiNames)} to produce the answer. Please do not send details about other people or sensitive information such as health data.`);
  if (analytics) collect.push(`How you use the app: the pages you view and the actions you take, with a random ID stored in your browser, and your device and browser type. ${list(analyticsNames)} collects this for us.`);
  if (errors) collect.push('When something goes wrong: the error details, the page and your browser type, so we can fix it.');
  if (upstash) collect.push('A short-lived count of requests from your IP address or account, used to slow down abuse.');
  collect.push('You need to give your email address and a password to have an account, because we cannot run the account without them. Everything else is optional.');
  collect.push('We do not collect more than the app needs to work.');
  privacy.push({ id: 'what-we-collect', title: 'What we collect', paragraphs: collect });

  const why = [
    ['Create your account and run the app for you', 'Contract: we need it to give you the service you asked for'],
    ['Keep the app secure, stop abuse, find and fix faults', 'Legitimate interest: running a safe service'],
    ['Answer the questions and requests you send us', 'Legitimate interest, and legal duty where the law asks for it'],
  ];
  if (google) why.push(['Let you sign in with Google', 'Contract: you chose to sign in this way']);
  if (billing) why.push(['Take payments, give refunds and keep invoices', 'Contract, and legal duty to keep accounting records']);
  if (ai) why.push(['Send what you enter in an AI feature to get the answer', 'Contract: you asked the feature to do it']);
  if (newsletter) why.push(['Send you email updates', 'Consent. You can take it back at any time']);
  if (analytics) why.push(['Measure how the app is used', 'Consent. You can take it back at any time']);
  if (errors) why.push(['Collect error reports', 'Legitimate interest: fixing faults quickly']);
  const whyParagraphs = [
    'The law asks us to have a reason for each use of your data. These are ours.',
    'We do not sell your data and we do not use it for advertising.',
  ];
  if (region === 'other') {
    whyParagraphs.push('We write this policy to the standard of the EU and UK data protection laws, which are among the strictest. The law where you live may give you more rights, and those apply too.');
  }
  privacy.push({ id: 'why-we-use-it', title: 'Why we use your data', paragraphs: whyParagraphs, table: { headers: ['What we do', 'Our reason'], rows: why } });

  const supa = i.supabaseRegion?.code ? regionLabel(i.supabaseRegion.code) : '';
  const processors = services.map((s) => {
    const where = s.id === 'supabase' && supa ? `${supa}` : s.location;
    const guard = safeguards(s);
    const protect = s.role === 'independent-controller'
      ? `${where}. Google acts for itself, so its own privacy policy applies`
      : guard ? `${where}. Protected by ${guard}` : where;
    return [s.name, s.purpose, s.dataShared, protect];
  });
  const whoParagraphs = [
    services.some((s) => s.role === 'independent-controller')
      ? 'We use these companies to run the app. Most of them handle your data only for us and only for the purpose shown. Google, when you choose to sign in with it, acts for itself, so its own privacy policy applies to that part.'
      : services.some((s) => s.role === 'processor-and-controller')
        ? 'We use these companies to run the app. Most of them handle your data only for us and only for the purpose shown. The exception is explained below.'
        : 'We use these companies to run the app. They handle your data for us and only for the purpose shown.',
  ];
  if (services.some((s) => s.role === 'processor-and-controller')) {
    whoParagraphs.push('Stripe processes payments for us. It is also responsible for its own fraud checks and legal duties, so its privacy policy applies to that part.');
  }
  whoParagraphs.push('Their privacy policies:');
  for (const s of services) whoParagraphs.push(`${s.name}: ${s.privacyUrl}`);
  const dpas = services.filter((s) => s.dpaUrl);
  if (dpas.length > 0) {
    whoParagraphs.push('The terms under which they handle personal data for us are published here:');
    for (const s of dpas) whoParagraphs.push(`${s.name}: ${s.dpaUrl}`);
  }
  privacy.push({
    id: 'who-processes-your-data',
    title: 'Who handles your data',
    paragraphs: whoParagraphs,
    table: { headers: ['Company', 'What it does', 'Data it handles', 'Where, and how it is protected'], rows: processors },
  });

  const guarded = services.filter((s) => safeguards(s));
  if (guarded.length > 0) {
    const lead = region === 'other'
      ? 'Some of these companies are based in, or work from, other countries than yours, so your data may travel across borders.'
      : 'Some of these companies are based in, or work from, countries outside the European Economic Area and the United Kingdom.';
    privacy.push({
      id: 'moving-data-abroad',
      title: 'Moving data to other countries',
      paragraphs: [
        lead,
        'Where the law asks for it, we rely on safeguards that the European Commission has approved: standard contractual clauses and, for companies that have joined it, the EU-US Data Privacy Framework. The table above shows which safeguard each company uses.',
      ],
    });
  }

  const keep = [
    'Your account and what you saved: until you delete your account. You can do this yourself at any time in Settings. It removes your account and your content from our database.',
    'Backup copies: our database provider may keep backups for a short time. Deleted data disappears from them when they expire.',
    'Technical logs at our hosting provider: for a short time, and at most 90 days.',
  ];
  if (billing) {
    keep.push(`Invoices and payment records: as long as accounting and tax law in ${place} requires. This can be several years, and it applies even after you delete your account.`);
    keep.push('Stripe keeps your customer record (your email address and your Stripe customer number) and your payment history as its own records require. Deleting your account here cancels your subscription, but does not erase what Stripe must keep.');
  }
  if (ai) keep.push(`${list(aiNames)} may keep what you send to an AI feature for a limited time to check for abuse. Their privacy policies, linked below, say for how long.`);
  if (resend) keep.push('Resend, which sends our emails, keeps a log of the emails it sent for a limited time.');
  if (newsletter) keep.push('Email updates: we keep your consent record, and your unsubscribe if you leave the list, while your account exists. We stop emailing you as soon as you unsubscribe.');
  if (analytics || errors) keep.push('Usage data and error reports: they are kept by the services named above for a limited time, which we keep as short as is useful.');
  privacy.push({ id: 'how-long-we-keep-it', title: 'How long we keep your data', paragraphs: keep });

  const authorityLine = {
    eea: `If you think we handle your data wrongly, you can complain to the data protection authority in your country, or in ${place}, where we are based. Find yours on the website of the European Data Protection Board: https://www.edpb.europa.eu/about-edpb/about-edpb/members_en`,
    uk: 'If you think we handle your data wrongly, you can complain to the Information Commissioner\'s Office, the data protection authority of the United Kingdom: https://ico.org.uk/make-a-complaint/',
    ch: 'If you think we handle your data wrongly, you can complain to the Federal Data Protection and Information Commissioner of Switzerland.',
    other: 'If you think we handle your data wrongly, you can complain to the data protection authority in the country where you live. If you live in the European Union, find yours on the website of the European Data Protection Board: https://www.edpb.europa.eu/about-edpb/about-edpb/members_en',
  }[region];
  privacy.push({
    id: 'your-rights',
    title: 'Your rights',
    paragraphs: [
      'You can ask us to show you the data we have about you, to correct it, to delete it, to limit how we use it, and to give you a copy you can take elsewhere.',
      'You can delete your account yourself at any time in Settings. For anything else, write to us at the address at the top of this page. We reply within one month.',
      ...(newsletter || analytics ? ['Where we use your data because you agreed, you can take your agreement back at any time. This does not change what we did before.'] : []),
      'You can also object to uses that are based on our legitimate interest.',
      authorityLine,
    ],
  });

  const cookieText = [
    'We use only the storage the app needs. One cookie keeps you signed in. A small note in your browser remembers your choices, such as light or dark mode. These are strictly necessary, so they do not need your consent.',
  ];
  if (analytics) {
    cookieText.push(`We also use ${list(analyticsNames)} to see how the app is used. It stores a random ID in your browser. We turn it on only if you agree in the cookie notice, and you can change your mind at any time.`);
  } else {
    cookieText.push('We do not use advertising or tracking cookies.');
  }
  privacy.push({ id: 'cookies', title: 'Cookies', paragraphs: cookieText });

  if (newsletter) {
    privacy.push({
      id: 'email-updates',
      title: 'Email updates',
      paragraphs: [
        'Email updates are optional. The box to sign up is never ticked for you. We only send updates to people who ticked it.',
        'Every update has an unsubscribe link, and you can also switch them off in Settings. When you do, we stop at once.',
        'Emails the app needs to send, such as confirming your email address or resetting your password, are not updates. You get those either way.',
      ],
    });
  }

  privacy.push({
    id: 'keeping-your-data-safe',
    title: 'Keeping your data safe',
    paragraphs: [
      'Data travels over encrypted connections (https). Passwords are stored scrambled. The database is set up so that each account can only read its own information.',
      'No system is perfectly safe. If a breach puts your rights at risk, we will tell you, and the authority, as the law requires.',
    ],
  });

  privacy.push({
    id: 'children',
    title: 'Children',
    paragraphs: [`${app} is not meant for anyone under ${minAge}. We do not knowingly collect data from them. If you think a child has made an account, write to us and we will delete it.`],
  });

  privacy.push({
    id: 'changes',
    title: 'Changes to this policy',
    paragraphs: ['If we change this policy, the date at the top changes. If the change matters to you, for example a new company that handles your data, we tell you in the app or by email before it applies.'],
  });

  privacy.push({
    id: 'contact',
    title: 'Contact',
    paragraphs: [`Questions about your data? Write to ${controller.email}${controller.phone ? `, call ${controller.phone}` : ''}, or write to ${controller.name}, ${controller.address}, ${controller.country}.`],
  });

  // ------------------------------------------------------------------ terms
  const terms = [];

  terms.push({
    id: 'the-service',
    title: 'The service',
    paragraphs: [
      `These terms are the agreement between you and ${controller.name} (${controller.country}) for the use of ${app}.`,
      ...(usefulDescription ? [`What the app does: ${usefulDescription}`] : []),
      'By creating an account or using the app, you agree to them. If you do not agree, please do not use the app.',
      'How we handle your personal data is explained in our privacy policy.',
    ],
  });

  terms.push({
    id: 'your-account',
    title: 'Your account',
    paragraphs: [
      `You must be at least ${minAge} to use the app.`,
      'Use a real email address that you can read, and keep your password to yourself. You are responsible for what happens under your account. Tell us at once if you think someone else got in.',
      'You can delete your account at any time in Settings.',
    ],
  });

  terms.push({
    id: 'fair-use',
    title: 'Fair use',
    paragraphs: [
      'Use the app within the law and with respect for other people.',
      'Do not try to break the app, to get into other people\'s accounts or data, to overload it, or to copy it in bulk with automated tools.',
      'We can suspend or close an account that breaks these rules. Where we can, we tell you why first.',
    ],
  });

  terms.push({
    id: 'your-content',
    title: 'What you save',
    paragraphs: [
      'What you save in the app stays yours. You give us permission to store it, to show it back to you, and to share it only where a feature of the app lets you share it. We need this permission to run the app.',
      'Only save what you have the right to save. We can remove content that breaks the law or these terms.',
    ],
  });

  if (ai) {
    terms.push({
      id: 'ai-features',
      title: 'AI features',
      paragraphs: [
        `Some features use AI models run by ${list(aiNames)}. What you enter in them is sent there to produce the answer, as the privacy policy explains.`,
        'AI answers can be wrong, out of date or incomplete. Check anything important before you rely on it. Do not use the answers as medical, legal or financial advice.',
        'Do not send information about other people, or sensitive information, unless you have the right to and it is needed.',
      ],
    });
  }

  if (billing && paid.length > 0) {
    const prices = paid.map((p) => `${p.name} costs ${formatPrice(p.priceCents, p.currency, p.interval)}.`);
    const months = paid.some((p) => p.interval !== 'year');
    const years = paid.some((p) => p.interval === 'year');
    const cancelWord = months && years ? 'renews every month or every year, depending on your plan,' : years ? 'renews every year' : 'renews every month';
    const sub = [
      ...prices,
      'You pay by card or the other methods shown at checkout. Stripe handles the payment. The price you pay, with any taxes, is shown before you confirm.',
      `Your subscription ${cancelWord} until you cancel. You can cancel at any time in Settings, under Billing. You keep your paid access until the end of the period you already paid for, and you are not charged again.`,
      'If we raise the price, we tell you at least 30 days before it applies to you, so you can cancel first.',
      'If a payment fails, Stripe tries again for a while. If it still fails, we may pause or end your paid access.',
    ];
    sub.push('Except as set out here, or where the law says otherwise, we do not refund time you have already paid for.');
    terms.push({ id: 'subscriptions-and-payments', title: 'Subscriptions and payments', paragraphs: sub });
    terms.push({
      id: 'right-to-withdraw',
      title: 'Your right to change your mind',
      paragraphs: [
        'If you live in the European Union, the European Economic Area or the United Kingdom, you have 14 days from the day you subscribe to change your mind and withdraw, without giving a reason.',
        'When you subscribe, you tick a box at checkout to say that you agree to these terms and that you ask us to start the service straight away.',
        `To withdraw, press "Withdraw from contract" in Settings, under Billing, within the 14 days. You can also write to ${controller.email}${controller.phone ? ` or call ${controller.phone}` : ''}. We refund what you paid, minus a share for the days you already used the service. We pay the refund back the same way you paid, within 14 days of hearing from you.`,
        'If you live elsewhere, the law where you live may give you similar rights, and those stay yours.',
      ],
    });
    if (freePlan) {
      const quota = freePlan.freeQuota;
      terms.push({
        id: 'free-plan',
        title: 'The free plan',
        paragraphs: [
          `The ${freePlan.name} plan costs nothing.${quota ? ` It includes up to ${quota.amount} ${quota.unit}.` : ''} Some features may need a paid plan.`,
          'We may change what the free plan includes. If we do, we tell you in the app first.',
        ],
      });
    }
  }

  terms.push({
    id: 'availability',
    title: 'Availability',
    paragraphs: [
      'We work to keep the app running, but we do not promise it will always be available or free of faults. We may stop it for maintenance, and we may change or remove features.',
      ...(billing && paid.length > 0 ? ['If we close the app or remove a paid feature, we refund the part of your payment that covers the time after that.'] : []),
    ],
  });

  terms.push({
    id: 'liability',
    title: 'Liability',
    paragraphs: [
      'The app is provided as it is. As far as the law allows, we are not responsible for indirect losses, lost profits or lost data that come from using it.',
      'Nothing in these terms limits liability that the law does not allow us to limit. This includes fraud, death or personal injury caused by our fault, and the rights you have as a consumer.',
    ],
  });

  terms.push({
    id: 'governing-law',
    title: 'Governing law',
    paragraphs: [
      `These terms follow the law of ${lawPlace}, and the courts of ${lawPlace} can decide disputes.`,
      'If you are a consumer, this does not take away the protection you have under the mandatory consumer law of the country where you live, and you may be able to go to a court there.',
    ],
  });

  terms.push({
    id: 'changes-to-terms',
    title: 'Changes to these terms',
    paragraphs: billing && paid.length > 0
      ? [
        'If we change these terms, the date at the top changes. If the change matters to you, we tell you in the app or by email before it applies.',
        'If a change is to your disadvantage, you can cancel before it applies and get back the unused part of what you paid. If you do not cancel and keep using the app after it applies, you accept the new terms.',
      ]
      : ['If we change these terms, the date at the top changes. If the change matters to you, we tell you in the app or by email before it applies. If you keep using the app after that, you accept the new terms.'],
  });

  terms.push({
    id: 'contact-us',
    title: 'Contact',
    paragraphs: [`Questions about these terms? Write to ${controller.email}${controller.phone ? `, call ${controller.phone}` : ''}, or write to ${controller.name}, ${controller.address}, ${controller.country}.`],
  });

  return { updatedAt: i.today, controller, privacy, terms };
}

// ------------------------------------------------------------------ safety net

const BAD_TEXT = [
  [/[\u2014\u2015]/, 'an em dash'],
  [/(?<![&\w])#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{3,4})(?![\w-])/, 'something that looks like a colour code'],
  [/(?<![\w$.])(?:alert|confirm|prompt)\(/, 'a call that looks like a browser pop-up'],
  [/\b(?:Tip|Pro tip):/, 'a tip box'],
  [/AI-powered|Powered by AI/i, 'an AI badge'],
  [/\[[A-Z][A-Z0-9 _-]{2,}\]|<[A-Z][A-Z0-9_]{2,}>|\{\{[^}]*\}\}|lorem ipsum|\bTODO\b|\bTBD\b|\bFIXME\b/i, 'a placeholder'],
  [/\p{Extended_Pictographic}/u, 'an emoji'],
  [/\b(?:RLS|JWT|API|schema|token)\b/i, 'a developer word'],
  [/\b(?:draft|have it checked)\b/i, 'the draft note (that belongs in chat and on the Health page)'],
];

/** Problems that would make the generated text break the app's own checks. Empty when fine. */
export function lintLegalContent(content) {
  const problems = [];
  const sections = [...content.privacy.map((s) => ['privacy', s]), ...content.terms.map((s) => ['terms', s])];
  for (const [where, s] of sections) {
    const text = [s.title, ...s.paragraphs, ...(s.table ? [...s.table.headers, ...s.table.rows.flat()] : [])].join('\n');
    for (const [re, what] of BAD_TEXT) {
      if (re.test(text)) problems.push(`${where} / ${s.title}: contains ${what}`);
    }
  }
  const fields = Object.values(content.controller).join('\n');
  for (const [re, what] of BAD_TEXT.slice(0, 3)) if (re.test(fields)) problems.push(`controller details contain ${what}`);
  return problems;
}

/** The text of src/lib/legal-content.ts. Same input gives byte-identical output. */
export function renderLegalFile(content) {
  const json = (v) => JSON.stringify(v, null, 2);
  return `${GENERATED_HEADER}
import type { LegalController, LegalSection } from "@/lib/legal-types";

/** The day this text was written (YYYY-MM-DD). */
export const updatedAt = ${json(content.updatedAt)};

/** Who is responsible for the app. */
export const controller: LegalController = ${json(content.controller)};

export const privacy: LegalSection[] = ${json(content.privacy)};

export const terms: LegalSection[] = ${json(content.terms)};
`;
}

/** Read back what a legal-content.ts holds, without compiling TypeScript. Returns null when it cannot be read. */
export function parseLegalFile(source) {
  try {
    const js = String(source)
      .replace(/^import .*$/gm, '')
      .replace(/: LegalController\b/g, '')
      .replace(/: LegalSection\[\]/g, '')
      .replace(/\bexport const (\w+)/g, 'exports.$1');
    const exports = {};
    runInNewContext(js, { exports }, { timeout: 1000 });
    if (typeof exports.updatedAt !== 'string' || !exports.controller || !Array.isArray(exports.privacy) || !Array.isArray(exports.terms)) return null;
    return exports;
  } catch {
    return null;
  }
}

export { parseCountry, privacyRegion, hasWithdrawalRight, isEea, isUk };
